'use client';

import { useEffect, useRef } from 'react';

type Props = {
  /** Необязательно: своя картинка вместо встроенной */
  src?: string;
  className?: string;
  /** Пауза между выстрелами гильз, мс */
  interval?: number;
  /** Вращать барабан */
  spin?: boolean;
};

type Shell = { x: number; y: number; vx: number; vy: number; r: number; vr: number; sc: number };

const W = 800, H = 1000, CX = 400, CY = 232, S = 0.5, TAU = Math.PI * 2;
const SRC = 797; // размер исходной картинки
const IC = { x: 397, y: 394 };
const P = ([
  [397.5, 161], [606, 280.5], [604.5, 507], [397, 627.5], [187.5, 506.5], [189, 280.5],
] as const).map(([x, y]) => ({ x: (x - IC.x) * S, y: (y - IC.y) * S }));

export default function RevolverShells({ src = ROLL_IMG, className, interval = 450, spin = true }: Props) {
  const ref = useRef<HTMLCanvasElement>(null);
  const spinRef = useRef(spin);

  useEffect(() => {
    spinRef.current = spin;
  }, [spin]);

  useEffect(() => {
    const cv = ref.current!;
    const ctx = cv.getContext('2d')!;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    cv.width = W * dpr;
    cv.height = H * dpr;

    const img = new Image();
    let ready = false;
    img.onload = () => { ready = true; };
    img.src = src;

    let rot = 0, raf = 0;
    let shells: Shell[] = [];
    const ch = P.map(() => ({ busy: false, cover: 0 }));
    const timers: number[] = [];

    const pos = (i: number) => {
      const c = Math.cos(rot), s = Math.sin(rot), p = P[i];
      return { x: CX + p.x * c - p.y * s, y: CY + p.x * s + p.y * c };
    };

    function drawHole(x: number, y: number, a: number) {
      ctx.save();
      ctx.globalAlpha = a;
      ctx.beginPath(); ctx.arc(x, y, 54.5, 0, TAU); ctx.fillStyle = '#05080d'; ctx.fill();
      const g = ctx.createRadialGradient(x - 10, y - 12, 4, x, y, 50);
      g.addColorStop(0, '#3d557a'); g.addColorStop(0.55, '#1a2740'); g.addColorStop(1, '#0a101b');
      ctx.beginPath(); ctx.arc(x, y, 50.5, 0, TAU); ctx.fillStyle = g; ctx.fill();
      ctx.beginPath(); ctx.arc(x, y, 45.5, Math.PI * 0.9, Math.PI * 1.55);
      ctx.strokeStyle = 'rgba(150,185,235,.75)'; ctx.lineWidth = 3.5; ctx.lineCap = 'round'; ctx.stroke();
      ctx.beginPath(); ctx.arc(x, y, 28, 0, TAU);
      ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(0,0,0,.55)'; ctx.stroke();
      ctx.restore();
    }

    function drawShell(s: Shell) {
      ctx.save();
      ctx.translate(s.x, s.y); ctx.rotate(s.r); ctx.scale(s.sc, s.sc);
      ctx.lineJoin = 'round'; ctx.strokeStyle = '#0b0f14'; ctx.lineWidth = 3.5;
      const g = ctx.createLinearGradient(0, -17, 0, 17);
      g.addColorStop(0, '#fff3a6'); g.addColorStop(0.3, '#f8c800');
      g.addColorStop(0.75, '#e8a000'); g.addColorStop(1, '#b86a00');
      ctx.beginPath();
      ctx.moveTo(-36, -17); ctx.lineTo(26, -17); ctx.lineTo(42, -14);
      ctx.lineTo(42, 14); ctx.lineTo(26, 17); ctx.lineTo(-36, 17); ctx.closePath();
      ctx.fillStyle = g; ctx.fill(); ctx.stroke();
      ctx.beginPath(); ctx.rect(-45, -20, 9, 40); ctx.fillStyle = '#f0b000'; ctx.fill(); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-27, -16); ctx.lineTo(-27, 16); ctx.lineWidth = 2; ctx.stroke();
      ctx.beginPath(); ctx.ellipse(42, 0, 3.5, 11, 0, 0, TAU); ctx.fillStyle = '#1a0f00'; ctx.fill();
      ctx.beginPath(); ctx.moveTo(-20, -10); ctx.lineTo(22, -10);
      ctx.strokeStyle = 'rgba(255,255,255,.8)'; ctx.lineWidth = 4; ctx.lineCap = 'round'; ctx.stroke();
      ctx.restore();
    }

    function fire() {
      const free = ch.map((c, i) => (c.busy ? -1 : i)).filter((i) => i >= 0);
      if (!free.length) return;
      const i = free[Math.floor(Math.random() * free.length)];
      const p = pos(i);
      ch[i].busy = true;
      ch[i].cover = 1;
      const dx = p.x - CX, dy = p.y - CY, m = Math.hypot(dx, dy) || 1;
      shells.push({
        x: p.x, y: p.y, sc: 2.4,
        vx: (dx / m) * (0.8 + Math.random() * 2.2) + (Math.random() - 0.5),
        vy: (dy / m) * 2 - 4 - Math.random() * 4,
        r: Math.random() * TAU, vr: (Math.random() - 0.5) * 0.45,
      });
      // каморка «перезаряжается»
      timers.push(window.setTimeout(() => { ch[i].busy = false; }, 1100));
    }

    function loop() {
      for (const s of shells) {
        s.sc += (1 - s.sc) * 0.09;
        s.vy += 0.55; s.x += s.vx; s.y += s.vy; s.r += s.vr;
      }
      shells = shells.filter((s) => s.y < H + 60);
      ch.forEach((c) => { if (!c.busy && c.cover > 0) c.cover = Math.max(0, c.cover - 0.06); });
      if (spinRef.current) rot += 0.004;

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, W, H);
      if (ready) {
        ctx.save();
        ctx.translate(CX, CY); ctx.rotate(rot);
        ctx.drawImage(img, -IC.x * S, -IC.y * S, SRC * S, SRC * S);
        ctx.restore();
      }
      ch.forEach((c, i) => { if (c.cover > 0.01) { const p = pos(i); drawHole(p.x, p.y, c.cover); } });
      shells.forEach(drawShell);
      raf = requestAnimationFrame(loop);
    }

    const timer = window.setInterval(fire, interval);
    loop();
    return () => {
      cancelAnimationFrame(raf);
      clearInterval(timer);
      timers.forEach(clearTimeout);
    };
  }, [src, interval]);

  return (
    <canvas
      ref={ref}
      className={className}
      aria-hidden="true"
      style={{ display: 'block', width: '100%', height: 'auto', background: 'transparent' }}
    />
  );
}

// Картинка барабана встроена в файл — ничего класть в public/ не нужно
const ROLL_IMG =
  'data:image/webp;base64,';
